#!/usr/bin/env bash
# Prints the release notes of VERSION: the body of its "## [VERSION] - date" section of CHANGELOG.md
# (generated by `mise run changelog`). Fails when the changelog has no such section, which is how the
# release workflow refuses a tag cut before the changelog was regenerated and committed.
#
# Usage: notes.sh VERSION            (VERSION without the "v", e.g. 0.1.0-rc.1)
# Environment: CHANGELOG overrides the file read (tests).
set -euo pipefail

version="${1:?usage: notes.sh VERSION}"
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
changelog="${CHANGELOG:-CHANGELOG.md}"

notes="$(awk -v header="## [$version]" '
  index($0, header) == 1 { found = 1; next }
  found && /^## \[/ { exit }
  found { print }
' "$changelog" | awk 'NF { started = 1 } started { lines[++n] = $0 } END { while (n > 0 && lines[n] == "") n--; for (i = 1; i <= n; i++) print lines[i] }')"
if [[ -z $notes ]]; then
  echo "notes.sh: no section \"## [$version]\" (or an empty one) in $changelog — run \`mise run changelog -- --tag v$version\` and commit it before tagging" >&2
  exit 1
fi
printf '%s\n' "$notes"
